#!/usr/bin/env bash
cd "$(git rev-parse --show-toplevel)"
# set -euo pipefail

# Expects animated work_*.blend files
# (outputs/blender/work_*.blend generated by run_animate*.sh)
#
# All sessions x all cameras are put into one global queue and render_sessions.py
# renders them dynamically per GPU slot, so GPUs never idle at session/camera boundaries.
#
# Default is warm mode: one resident blender per GPU slot, fed with chunks.
# .blend loading / GPU init / BVH build only happen when switching sessions.
# Use --cold to go back to the old 'start blender for every chunk' behavior.
# For flag details: python scripts/05_create_digital_twin/render_sessions.py --help

PY=$(command -v python || command -v python3)
exec "$PY" scripts/05_create_digital_twin/render_sessions.py "$@"
